// The push half of the service worker. dist/sw.js is generated by workbox (see
// workbox-config.js), so this is not registered on its own: the generated worker pulls it
// in with importScripts, and the browser byte-checks it with every update of the worker.
// Plain ES5-ish JS on purpose — it is served as-is, not bundled.
//
// The payload is JSON from supabase/functions/send-push: { title, body, tag, url }. The
// text is already in the subscriber's language; nothing is translated here.

self.addEventListener('push', (event) => {
  const data = (() => {
    try {
      return event.data ? event.data.json() : {}
    } catch (error) {
      return {}
    }
  })()

  // Never return without showing something: the subscription is `userVisibleOnly`, so a push
  // that shows nothing makes the browser put up its own "updated in the background" notice,
  // and enough of those and Safari drops the subscription. An unreadable payload gets the
  // plainest honest line instead.
  event.waitUntil(
    self.registration.showNotification(data.title || 'nine', {
      body: data.title ? data.body : 'Something happened on the boards.',
      // One notification per board: a second takeover replaces the first instead of
      // stacking.
      tag: data.tag,
      icon: '/pwa-192.png',
      badge: '/pwa-192.png',
      data: { url: data.url || '/' },
    }),
  )
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const url = (event.notification.data && event.notification.data.url) || '/'

  event.waitUntil(
    self.clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then((clients) => {
        const open = clients[0]
        if (open && 'focus' in open) return open.focus()
        return self.clients.openWindow(url)
      }),
  )
})
